<script type="text/javascript">
function main() {
  // Load a JSON file into a variable.
  var data = {
    "title": "Post Card",
    "description": "This post card showcases the beauty of nature through lush vegetation and gentle hues."
  };

  // Render the JSON data as an HTML table.
  var table = document.createElement("table");
  table.setAttribute("class", "data-table"));
  for (var key in data) {
    var row = document.createElement("tr");
    row.innerHTML = key + ": " + data[key];
    table.appendChild(row);
  }
  document.body.appendChild(table);
}
</script>
